std::string activity_name(ActivityKind k){static const char*names[]={"Idle","Work","Travel","Meal preparation","Drink","Rest","Conversation","Study","Collect water","Self care","Journey"};return names[int(k)];}
namespace {
std::string q(const std::string&s){std::string out="\"";const char*hex="0123456789abcdef";for(unsigned char c:s){if(c=='"'||c=='\\'){out+='\\';out+=char(c);}else if(c<32){out+="\\u00";out+=hex[c>>4];out+=hex[c&15];}else out+=char(c);}return out+'"';}
void inv(std::ostream&o,const Inventory&i){o<<'[';for(int j=0;j<goods;++j){if(j)o<<',';o<<i.units[j];}o<<']';}
}
