 o<<"{\"rules\":\"trial-b1\",\"fixture_regions\":"<<s.fixture_regions<<",\"seed\":"<<s.seed<<",\"tick\":"<<s.tick<<",\"revision\":"<<s.revision<<",\"viewer\":"<<viewer<<",\"debug\":"<<(debug?"true":"false")<<",\"treasury\":"<<s.government.account.money<<",\"office_holder\":"<<s.government.office.holder;
