 o<<",\"citizens\":[";bool first=true;for(auto&[id,p]:s.people){if(!debug&&id!=viewer&&!co_located(s,viewer,id))continue;if(!first)o<<',';first=false;o<<"{\"id\":"<<id<<",\"name\":"<<q(p.name)<<'}';}o<<']';
 o<<",\"routes\":[";first=true;for(auto&[id,r]:s.routes){if(!first)o<<',';first=false;o<<"{\"id\":"<<id<<",\"name\":"<<q(r.name)<<",\"from\":"<<r.from<<",\"to\":"<<r.to<<",\"length\":"<<r.length<<",\"capacity\":"<<r.capacity<<",\"toll\":"<<r.toll<<",\"collector\":"<<r.collector<<",\"camp\":"<<r.camp.id<<",\"road\":"<<r.road.id;if(debug||viewer==r.controller||v.location==r.from||v.location==r.to||v.location==r.camp.id||v.location==r.road.id)o<<",\"open\":"<<(r.open?"true":"false");o<<'}';}o<<']';
