 o<<",\"proposals\":[";first=true;for(auto& p:s.proposals){if(!debug&&p.from!=viewer&&p.to!=viewer&&!(p.to==0&&p.site==v.location&&p.status==ContractStatus::Pending))continue;if(!first)o<<',';first=false;o<<"{\"id\":"<<p.id<<",\"kind\":"<<int(p.kind)<<",\"from\":"<<p.from<<",\"to\":"<<p.to<<",\"author\":"<<p.author<<",\"awaiting\":"<<p.awaiting<<",\"site\":"<<p.site<<",\"good\":"<<int(p.good)<<",\"amount\":"<<p.amount<<",\"price\":"<<p.price<<",\"duration\":"<<p.duration<<",\"deadline\":"<<p.deadline<<",\"status\":"<<int(p.status)<<",\"escrow\":"<<p.escrow<<",\"reserved\":";inv(o,p.reserved);o<<'}';}o<<']';
