 o<<",\"leases\":[";first=true;for(auto& l:s.leases){if(!debug&&l.landlord!=viewer&&l.tenant!=viewer)continue;if(!first)o<<',';first=false;o<<"{\"id\":"<<l.id<<",\"landlord\":"<<l.landlord<<",\"tenant\":"<<l.tenant<<",\"site\":"<<l.site<<",\"end\":"<<l.end<<",\"rent\":"<<l.rent<<",\"status\":"<<l.status<<'}';}o<<']';
 o<<",\"actions\":[";first=true;for(auto&a:World::definitions()){if(!first)o<<',';first=false;o<<"{\"verb\":"<<q(a.verb)<<",\"parameters\":"<<q(a.parameters)<<",\"description\":"<<q(a.description)<<",\"named\":[";bool nf=true;for(auto& name:action_registry().at(a.verb).named_parameters){if(!nf)o<<',';nf=false;o<<q(name);}o<<"]}";}o<<"]}";return o.str();
